/-- The selected contrast obeys the Lipschitz modulus with radius three. -/
def ContrastLipschitz : Prop :=
  ∀ x x', |tau P x - tau P x'| ≤ L * |(x : ℝ) - x'| -- @realizes tau(Lipschitz radius 3)

/-- The selected control regression obeys the one-tenth Holder modulus with radius three. -/
def ControlHolder : Prop :=
  ∀ x x', |P.mu0 x - P.mu0 x'| ≤ L * |(x : ℝ) - x'| ^ (1/10 : ℝ) -- @realizes mu0(Holder radius 3)

/-- The potential-outcome pair and treatment are conditionally independent given the covariate. -/
def Exchangeability : Prop :=
  CondIndepFun (MeasurableSpace.comap X inferInstance) measurable_X.comap_le Ypot A P.law

/-- The selected propensity obeys the one-tenth Holder modulus with radius three. -/
def PropensityHolder : Prop :=
  ∀ x x', |P.e x - P.e x'| ≤ L * |(x : ℝ) - x'| ^ (1/10 : ℝ) -- @realizes e(Holder 1/10 radius 3)

/-- The inversion accepts exactly the target-range candidates satisfying the specified floored and
clipped affine inequality. -/
def acceptedSet (v : Fin 2 → ℝ) : Set ℝ :=
  let bd := max (d0 n h k) (v 1)
  let bn := clip (-bd) bd (v 0)
  {vartheta | vartheta ∈ Icc (-1) 1 ∧
    |bn - vartheta*bd| ≤ Real.sqrt (10*Vbound n epsilon h k)*bd}

/-- The alternative propensity is one half plus the specified shared-sign perturbation. -/
def altE (lam : SignVector hL) (x : Covariate) : ℝ :=
  (1 + Real.sqrt (separation hL)*perturbation hL lam x)/2

/-- The alternative control mean has the negative shared-sign term and negative effect bump. -/
def altMu0 (lam : SignVector hL) (x : Covariate) : ℝ :=
  (1 - Real.sqrt (separation hL)*perturbation hL lam x - separation hL*bump hL x)/2

/-- The alternative treated mean has the negative shared-sign term and positive effect bump. -/
def altMu1 (lam : SignVector hL) (x : Covariate) : ℝ :=
  (1 - Real.sqrt (separation hL)*perturbation hL lam x + separation hL*bump hL x)/2

/-- The same covariate vector is attached to a vector of treatment-outcome marks. -/
def attachMarks (x : Fin n → Covariate) (z : Fin n → Bool × Bool) : Dataset n :=
  fun i => (x i, (z i).1, (z i).2)

/-- Public cells partition the localization window with left endpoints included and only the final
right endpoint included. -/
def cell (j : Fin k) : Set Covariate :=
  {x | (x0 : ℝ) - h + j.val * cellWidth h k ≤ (x : ℝ) ∧
    ((x : ℝ) < (x0 : ℝ) - h + (j.val+1) * cellWidth h k ∨
      (j.val+1 = k ∧ (x : ℝ) = (x0 : ℝ) + h))}

/-- A cell selects the dataset indices whose covariates belong to that public cell. -/
def cellRecords (D : Dataset n) (j : Fin k) : Finset (Fin n) :=
  Finset.univ.filter (fun i => (D i).1 ∈ cell h k j)

/-- A cell moment sum adds a record function across the selected dataset indices. -/
def cellSum (D : Dataset n) (j : Fin k) (v : O → ℝ) : ℝ :=
  ∑ i ∈ cellRecords n h k D j, v (D i)

