/-- The common mass is the pointwise minimum of the alternative and null component masses. -/
def commonMass (x : Fin n → Covariate) (C : Finset (Fin n)) (z : Marks C) : ℝ :=
  min (alternativeMass hL n x C z) (nullMass n C z)

/-- Each component is represented by its least vertex. -/
def componentRoots (x : Fin n → Covariate) : Finset (Fin n) :=
  Finset.univ.filter (fun i => ∀ l, (sharedGraph hL n x).Reachable i l → i ≤ l)

/-- A graph component contains exactly the vertices reachable from its selected vertex. -/
def componentVertices (x : Fin n → Covariate) (i : Fin n) : Finset (Fin n) :=
  Finset.univ.filter (fun l => (sharedGraph hL n x).Reachable i l)

/-- The conditional record law is the observed marginal restricted to the cell and normalized by
its mass. -/
def conditionalCellLaw (P : CausalLaw) (j : Fin k) : Measure O :=
  ((Pobs P) {z | z.1 ∈ cell h k j})⁻¹ • (Pobs P).restrict {z | z.1 ∈ cell h k j}

/-- A normalized exact label event is a probability measure. The result uses [the stated assumptions](hyp:hp) and establishes [the displayed conclusion](goal). -/
-- @node: conditional_membership_probability
lemma conditional_membership_probability (n k : ℕ) (h : ℝ) (P : CausalLaw)
    (j : Fin k) (I : Finset (Fin n))
    (hp : ∀ r : Fin n, (Pobs P)
      (if r ∈ I then {z : O | z.1 ∈ cell h k j}
        else {z : O | z.1 ∈ cell h k j}ᶜ) ≠ 0) :
    IsProbabilityMeasure (((dataLaw n P) {D | cellRecords n h k D j = I})⁻¹ •
      (dataLaw n P).restrict {D | cellRecords n h k D j = I}) := by
  classical
  let : IsProbabilityMeasure (Pobs P) :=
    Measure.isProbabilityMeasure_map measurable_observe.aemeasurable
  rw [iid_conditional_membership_law n k h P j I hp]
  let : ∀ r : Fin n, IsProbabilityMeasure
      (((Pobs P) (if r ∈ I then {z : O | z.1 ∈ cell h k j}
        else {z : O | z.1 ∈ cell h k j}ᶜ))⁻¹ •
        (Pobs P).restrict (if r ∈ I then {z : O | z.1 ∈ cell h k j}
          else {z : O | z.1 ∈ cell h k j}ᶜ)) :=
    fun r => normalized_record_restriction_probability (Pobs P) _ (hp r)
  infer_instance

/-- Coverage is the probability that the randomized coded interval contains the law-specific point
target. -/
def coverage (I : Kernel (Dataset n) IntervalCode) (P : CausalLaw) : ℝ :=
  (I ∘ₘ dataLaw n P).real {c | theta P ∈ c.toSet}

/-- The dataset law is the finite product of the observed marginal. -/
def dataLaw (n : ℕ) (P : CausalLaw) : Measure (Dataset n) :=
  Measure.pi (fun _ : Fin n => Pobs P)

/-- The denominator cell contribution uses the displayed closed treatment moment formula, with
zero below occupancy two. -/
def denominatorCell (D : Dataset n) (j : Fin k) : ℝ :=
  let s := cellCount n h k D j
  let a := cellSum n h k D j (fun z => bit z.2.1)
  if s < 2 then 0 else 2 * ((s : ℝ) * a - a^2) / ((s : ℝ) - 1)

/-- The conditional denominator moment integrates its pair kernel under those independent draws. -/
def dj (P : CausalLaw) (j : Fin k) : ℝ :=
  ∫ zz, KD zz.1 zz.2 ∂((conditionalCellLaw h k P j).prod (conditionalCellLaw h k P j))

/-- The macro envelope is the squared cosine inside the localization window and zero outside. -/
def envelope (x : Covariate) : ℝ :=
  if |(x : ℝ) - x0| ≤ hL then (Real.cos (Real.pi*((x : ℝ)-x0)/(2*hL)))^2 else 0

/-- A finite prior uniformly averages the observed product laws of its constituent causal laws. -/
def finiteProductMixture (n s : ℕ) (family : Fin s → CausalLaw) : Measure (Dataset n) :=
  (s : ℝ≥0∞)⁻¹ • ∑ i : Fin s, dataLaw n (family i)

/-- The public occupancy scale is sample size times radius times the truncated expected cell
occupancy. -/
def info : ℝ := n*h*min 1 (n*cellWidth h k)

