/-- The event that all edges of a specified labeled tree share signs on selected coordinates.
Extra graph edges and all isolation requirements are deliberately discarded. -/
-- @node: labeledSharedTreeEvent
def labeledSharedTreeEvent (hL : ℝ) (n s : ℕ) (e : Fin s → Fin n)
    (T : SimpleGraph (Fin s)) : Set (Fin n → Covariate) :=
  {x | ∀ i j, T.Adj i j → sharedAdj hL n x (e i) (e j)}

/-- The same absolute-risk criterion without a privacy restriction. -/
def nonprivateMinimaxRisk : ℝ≥0∞ :=
  ⨅ (T : Kernel (Dataset n) ℝ) (_ : IsMarkovKernel T), worstRisk n T

/-- The null component measure is the finite measure with the specified fair mark masses. -/
def nullComponentLaw (C : Finset (Fin n)) : Measure (Marks C) :=
  ∑ z : Marks C, ENNReal.ofReal (nullMass n C z) • Measure.dirac z

/-- The fair component mark law gives every configuration mass four to the power minus component
size. -/
def nullMass (C : Finset (Fin n)) (_z : Marks C) : ℝ := (4 : ℝ)^(-(C.card : ℤ))

/-- Components are selected by increasing least vertex, so the construction is deterministic. -/
def orderedComponents (x : Fin n → Covariate) : List (Finset (Fin n)) :=
  ((componentRoots hL n x).sort (· ≤ ·)).map (componentVertices hL n x)

/-- The rooted geometric event obtained by successively adding a child whose parent is a
function of the earlier covariates. Coordinate projections give ordinary ordered labeled trees. -/
-- @node: orderedTreeRegion
def orderedTreeRegion (h d : ℝ)
    (parent : (m : ℕ) → (Fin (m + 1) → Covariate) → Covariate) :
    (m : ℕ) → Set (Fin (m + 1) → Covariate)
  | 0 => {x | |(x 0 : ℝ) - x0| < h}
  | m+1 => {x | (fun i : Fin (m + 1) => x i.castSucc) ∈ orderedTreeRegion h d parent m ∧
      |(x (Fin.last (m + 1)) : ℝ) - parent m (fun i : Fin (m + 1) => x i.castSucc)| < 2 * d}

/-- Total overlap sums the common component masses. -/
def overlapMass (x : Fin n → Covariate) (C : Finset (Fin n)) : ℝ :=
  ∑ z : Marks C, commonMass hL n x C z

/-- The nuisance perturbation multiplies the signed frame sum by the macro envelope. -/
def perturbation (lam : SignVector hL) (x : Covariate) : ℝ :=
  envelope hL x * ∑ j : activeSigns hL, (2*bit (lam j)-1)*frame hL j x

/-- Public tuning returns the entire target range in the constant branch and otherwise uses the
conservative pair-ratio interval. -/
def publicTunedInterval : Kernel (Dataset n) IntervalCode :=
  if 1/8 ≤ rate n epsilon then Kernel.const _ (Measure.dirac (closedInterval (-1) 1))
  else Ihk n epsilon (tunedH n epsilon) (tunedK n epsilon)

/-- Public tuning returns zero in the constant branch and otherwise uses the specified dyadic
pair-ratio release. -/
def publicTunedRelease : Kernel (Dataset n) ℝ :=
  if 1/8 ≤ rate n epsilon then Kernel.const _ (Measure.dirac 0)
  else Thk n epsilon (tunedH n epsilon) (tunedK n epsilon)

/-- The scalar postprocessing floors the noisy denominator and clips the ratio to the target
range. -/
def ratioMap (v : Fin 2 → ℝ) : ℝ := clip (-1) 1 (v 0 / max (d0 n h k) (v 1))

/-- Absolute risk integrates both the observed dataset distribution and randomized scalar output. -/
def scalarRisk (T : Kernel (Dataset n) ℝ) (P : CausalLaw) : ℝ≥0∞ :=
  ∫⁻ u, ENNReal.ofReal |u - theta P| ∂(T ∘ₘ dataLaw n P)

